package got.wildlife;
import net.minecraft.world.effect.*; import net.minecraft.world.entity.*; import net.minecraft.world.entity.ai.attributes.*; import net.minecraft.world.entity.ai.goal.*; import net.minecraft.world.entity.ai.goal.target.NearestAttackableTargetGoal; import net.minecraft.world.entity.monster.Monster; import net.minecraft.world.entity.player.Player; import net.minecraft.world.level.Level;
/** ASOIAF manticore: the small venomous insect, not the later fantasy lion-creature. */
public final class GOTManticoreEntity extends Monster { public GOTManticoreEntity(EntityType<? extends GOTManticoreEntity> t,Level l){super(t,l);xpReward=10;} public static AttributeSupplier.Builder createAttributes(){return Mob.createMobAttributes().add(Attributes.MAX_HEALTH,12).add(Attributes.MOVEMENT_SPEED,.34).add(Attributes.ATTACK_DAMAGE,4).add(Attributes.FOLLOW_RANGE,20);} protected void registerGoals(){goalSelector.addGoal(1,new FloatGoal(this));goalSelector.addGoal(2,new MeleeAttackGoal(this,1.25,true));goalSelector.addGoal(5,new WaterAvoidingRandomStrollGoal(this,1));targetSelector.addGoal(1,new NearestAttackableTargetGoal<>(this,Player.class,true));} public boolean doHurtTarget(net.minecraft.world.entity.Entity e){boolean h=super.doHurtTarget(e);if(h&&e instanceof net.minecraft.world.entity.LivingEntity l)l.addEffect(new MobEffectInstance(MobEffects.POISON,240,1));return h;} }
